     1→import React, { useEffect } from 'react';
     2→import { View, Text, StyleSheet, Dimensions, Platform } from 'react-native';
     3→import LottieView from 'lottie-react-native';
     4→import { useTheme } from '../../contexts/ThemeContext';
     5→
     6→interface LoadingSpinnerProps {
     7→  text?: string;
     8→  size?: 'small' | 'medium' | 'large';
     9→  style?: any;
    10→  source?: any; // optional override for Lottie source
    11→  offsetY?: number; // optional vertical offset
    12→}
    13→
    14→const LoadingSpinner: React.FC<LoadingSpinnerProps> = ({
    15→  text,
    16→  size = 'large',
    17→  style,
    18→  source,
    19→  offsetY = 0,
    20→}) => {
    21→  const { currentTheme } = useTheme();
    22→
    23→  // Android-specific Lottie configuration
    24→  useEffect(() => {
    25→    if (Platform.OS === 'android') {
    26→      // Enable merge paths for Android KitKat and above
    27→      try {
    28→        const Lottie = require('lottie-react-native');
    29→        if (Lottie.enableMergePathsForKitKatAndAbove) {
    30→          Lottie.enableMergePathsForKitKatAndAbove(true);
    31→        }
    32→      } catch (error) {
    33→        console.warn('Failed to enable merge paths for Android:', error);
    34→      }
    35→    }
    36→  }, []);
    37→  
    38→  const getSizeStyles = () => {
    39→    // Ensure dimensions are whole numbers for Android compatibility
    40→    const getWholeNumber = (num: number) => Math.round(num);
    41→    
    42→    switch (size) {
    43→      case 'small':
    44→        return { width: getWholeNumber(60), height: getWholeNumber(60) };
    45→      case 'medium':
    46→        return { width: getWholeNumber(100), height: getWholeNumber(100) };
    47→      case 'large':
    48→      default:
    49→        return { width: getWholeNumber(150), height: getWholeNumber(150) };
    50→    }
    51→  };
    52→
    53→  const getTextSize = () => {
    54→    switch (size) {
    55→      case 'small':
    56→        return 12;
    57→      case 'medium':
    58→        return 14;
    59→      case 'large':
    60→      default:
    61→        return 16;
    62→    }
    63→  };
    64→
    65→  return (
    66→    <View style={[styles.container, { transform: [{ translateY: offsetY }] }, style]}>
    67→      <LottieView
    68→        source={source || require('../../../assets/lottie/loading.json')}
    69→        autoPlay
    70→        loop
    71→        style={[styles.animation, getSizeStyles()]}
    72→        resizeMode="contain"
    73→        // Android-specific props
    74→        {...(Platform.OS === 'android' && {
    75→          hardwareAccelerationAndroid: true,
    76→          renderMode: 'SOFTWARE' as any, // Fallback to software rendering if hardware fails
    77→        })}
    78→        // Error handling
    79→        onAnimationFinish={() => {
    80→          if (__DEV__) console.log('Lottie animation finished');
    81→        }}
    82→        onAnimationFailure={(error) => {
    83→          if (__DEV__) console.warn('Lottie animation failed:', error);
    84→        }}
    85→      />
    86→      {text && (
    87→        <Text style={[
    88→          styles.text, 
    89→          { 
    90→            color: currentTheme.colors.textMuted,
    91→            fontSize: getTextSize()
    92→          }
    93→        ]}>
    94→          {text}
    95→        </Text>
    96→      )}
    97→    </View>
    98→  );
    99→};
   100→
   101→const styles = StyleSheet.create({
   102→  container: {
   103→    justifyContent: 'center',
   104→    alignItems: 'center',
   105→  },
   106→  animation: {
   107→    // Size will be set by getSizeStyles()
   108→  },
   109→  text: {
   110→    marginTop: 16,
   111→    textAlign: 'center',
   112→    fontWeight: '500',
   113→  },
   114→});
   115→
   116→export default LoadingSpinner;
   117→

