     1→import { ViewStyle, TextStyle } from 'react-native';
     2→import type { SharedValue } from 'react-native-reanimated';
     3→
     4→/**
     5→ * Available loading indicator variants
     6→ * - spinner: Animated Lottie or native ActivityIndicator
     7→ * - skeleton: Shimmer placeholder for content
     8→ * - shimmer: Animated shimmer effect overlay
     9→ * - branded: Custom branded loading (e.g., TraktLoadingSpinner)
    10→ */
    11→export type LoadingVariant = 'spinner' | 'skeleton' | 'shimmer' | 'branded';
    12→
    13→/**
    14→ * Standard loading indicator sizes
    15→ * - small: 24px - For inline/button loading states
    16→ * - medium: 40px - For section/card loading states
    17→ * - large: 60px - For full-screen/prominent loading states
    18→ */
    19→export type LoadingSize = 'small' | 'medium' | 'large';
    20→
    21→/**
    22→ * Size dimensions in pixels for each loading size
    23→ */
    24→export const LOADING_SIZE_DIMENSIONS: Record<LoadingSize, number> = {
    25→  small: 24,
    26→  medium: 40,
    27→  large: 60,
    28→} as const;
    29→
    30→/**
    31→ * Lottie animation dimensions (larger to accommodate animation details)
    32→ * These are used specifically for Lottie-based spinners
    33→ */
    34→export const LOTTIE_SIZE_DIMENSIONS: Record<LoadingSize, number> = {
    35→  small: 60,
    36→  medium: 100,
    37→  large: 150,
    38→} as const;
    39→
    40→/**
    41→ * Text font sizes corresponding to loading sizes
    42→ */
    43→export const LOADING_TEXT_SIZES: Record<LoadingSize, number> = {
    44→  small: 12,
    45→  medium: 14,
    46→  large: 16,
    47→} as const;
    48→
    49→/**
    50→ * Animation durations in milliseconds
    51→ */
    52→export const LOADING_ANIMATION_DURATIONS = {
    53→  /** Duration for shimmer animation cycle */
    54→  shimmer: 1500,
    55→  /** Duration for fade-in animations */
    56→  fadeIn: 300,
    57→  /** Duration for fade-out animations */
    58→  fadeOut: 200,
    59→  /** Stagger delay between animated elements */
    60→  staggerDelay: 100,
    61→} as const;
    62→
    63→/**
    64→ * Base props interface shared across all loading components
    65→ */
    66→export interface BaseLoadingProps {
    67→  /** Optional loading text to display below the indicator */
    68→  text?: string;
    69→  /** Size variant of the loading indicator */
    70→  size?: LoadingSize;
    71→  /** Custom container style */
    72→  style?: ViewStyle;
    73→  /** Test identifier for testing frameworks */
    74→  testID?: string;
    75→}
    76→
    77→/**
    78→ * Props for spinner-based loading components
    79→ */
    80→export interface SpinnerLoadingProps extends BaseLoadingProps {
    81→  /** Override default color (defaults to theme primary) */
    82→  color?: string;
    83→  /** Custom Lottie animation source */
    84→  source?: any;
    85→  /** Vertical offset from center */
    86→  offsetY?: number;
    87→}
    88→
    89→/**
    90→ * Props for skeleton/shimmer loading components
    91→ */
    92→export interface SkeletonLoadingProps {
    93→  /** Width of the skeleton element (number in pixels or string percentage) */
    94→  width: number | string;
    95→  /** Height of the skeleton element in pixels */
    96→  height: number;
    97→  /** Border radius of the skeleton element */
    98→  borderRadius?: number;
    99→  /** Margin below the skeleton element */
   100→  marginBottom?: number;
   101→  /** Custom style for the skeleton container */
   102→  style?: ViewStyle;
   103→  /** Test identifier for testing frameworks */
   104→  testID?: string;
   105→  /** Shared animation progress value for synchronized animations */
   106→  shimmerProgress?: SharedValue<number>;
   107→}
   108→
   109→/**
   110→ * Props for skeleton group components
   111→ */
   112→export interface SkeletonGroupProps {
   113→  /** Number of skeleton items to render */
   114→  count: number;
   115→  /** Preset configuration type */
   116→  preset?: SkeletonPreset;
   117→  /** Gap between skeleton items in pixels */
   118→  gap?: number;
   119→  /** Enable staggered fade-in animation */
   120→  staggered?: boolean;
   121→  /** Custom container style */
   122→  style?: ViewStyle;
   123→  /** Test identifier for testing frameworks */
   124→  testID?: string;
   125→  /** Custom render function for skeleton items */
   126→  renderItem?: (index: number, shimmerProgress: SharedValue<number>) => React.ReactNode;
   127→}
   128→
   129→/**
   130→ * Preset skeleton configurations for common content types
   131→ */
   132→export type SkeletonPreset = 'list' | 'grid' | 'textBlock' | 'poster' | 'episode' | 'cast' | 'catalogRow';
   133→
   134→/**
   135→ * Props for full-screen loading overlay
   136→ */
   137→export interface LoadingOverlayProps extends BaseLoadingProps {
   138→  /** Whether to show the overlay */
   139→  visible: boolean;
   140→  /** Enable backdrop blur effect */
   141→  blur?: boolean;
   142→  /** Custom backdrop opacity (0-1) */
   143→  backdropOpacity?: number;
   144→  /** Callback when backdrop is pressed (if dismissable) */
   145→  onBackdropPress?: () => void;
   146→}
   147→
   148→/**
   149→ * Color tokens for loading states
   150→ * These should be derived from the current theme
   151→ */
   152→export interface LoadingColorTokens {
   153→  /** Primary spinner/indicator color */
   154→  primary: string;
   155→  /** Secondary/muted color for loading text */
   156→  textMuted: string;
   157→  /** Base color for skeleton backgrounds */
   158→  skeletonBase: string;
   159→  /** Highlight color for shimmer effect */
   160→  skeletonHighlight: string;
   161→  /** Overlay/backdrop color */
   162→  overlay: string;
   163→}
   164→
   165→/**
   166→ * Helper function to get loading color tokens from theme colors
   167→ * @param themeColors - Colors object from the current theme
   168→ * @returns LoadingColorTokens with theme-appropriate values
   169→ */
   170→export function getLoadingColorTokens(themeColors: {
   171→  primary: string;
   172→  textMuted: string;
   173→  elevation1?: string;
   174→  transparentDark?: string;
   175→}): LoadingColorTokens {
   176→  return {
   177→    primary: themeColors.primary,
   178→    textMuted: themeColors.textMuted,
   179→    skeletonBase: themeColors.elevation1 || 'rgba(255, 255, 255, 0.08)',
   180→    skeletonHighlight: 'rgba(255, 255, 255, 0.12)',
   181→    overlay: themeColors.transparentDark || 'rgba(0, 0, 0, 0.7)',
   182→  };
   183→}
   184→
   185→/**
   186→ * Default loading configuration
   187→ */
   188→export const DEFAULT_LOADING_CONFIG = {
   189→  size: 'medium' as LoadingSize,
   190→  skeletonBorderRadius: 8,
   191→  skeletonMarginBottom: 8,
   192→  overlayBackdropOpacity: 0.7,
   193→} as const;
   194→
   195→/**
   196→ * Responsive breakpoints for loading components
   197→ * Matches the breakpoints used in MetadataLoadingScreen
   198→ */
   199→export const LOADING_BREAKPOINTS = {
   200→  phone: 0,
   201→  tablet: 768,
   202→  largeTablet: 1024,
   203→  tv: 1440,
   204→} as const;
   205→
   206→/**
   207→ * Device type based on screen width
   208→ */
   209→export type DeviceType = 'phone' | 'tablet' | 'largeTablet' | 'tv';
   210→
   211→/**
   212→ * Helper to determine device type from screen width
   213→ * @param width - Screen width in pixels
   214→ * @returns DeviceType based on breakpoints
   215→ */
   216→export function getDeviceType(width: number): DeviceType {
   217→  if (width >= LOADING_BREAKPOINTS.tv) return 'tv';
   218→  if (width >= LOADING_BREAKPOINTS.largeTablet) return 'largeTablet';
   219→  if (width >= LOADING_BREAKPOINTS.tablet) return 'tablet';
   220→  return 'phone';
   221→}
   222→
   223→/**
   224→ * Get responsive padding based on device type
   225→ * @param deviceType - Current device type
   226→ * @returns Horizontal padding value in pixels
   227→ */
   228→export function getResponsivePadding(deviceType: DeviceType): number {
   229→  switch (deviceType) {
   230→    case 'tv':
   231→      return 48;
   232→    case 'largeTablet':
   233→      return 32;
   234→    case 'tablet':
   235→      return 24;
   236→    default:
   237→      return 16;
   238→  }
   239→}
   240→

