    18→/**
    19→ * UnifiedSpinner - A theme-aware loading spinner component
    20→ *
    21→ * Provides a consistent loading indicator across the app with:
    22→ * - Theme-aware colors (uses currentTheme.colors.primary by default)
    23→ * - Three sizes: small (24px), medium (40px), large (60px)
    24→ * - Lottie animation support with fallback to native ActivityIndicator
    25→ * - Optional loading text with proper styling
    26→ * - Android-specific optimizations for Lottie animations
    27→ *
    28→ * @example
    29→ * // Basic usage with default size (medium)
    30→ * <UnifiedSpinner />
    31→ *
    32→ * @example
    33→ * // With loading text
    34→ * <UnifiedSpinner text="Loading content..." size="large" />
    35→ *
    36→ * @example
    37→ * // With custom color (e.g., white for button context)
    38→ * <UnifiedSpinner size="small" color="#FFFFFF" />
    39→ *
    40→ * @example
    41→ * // With custom Lottie source
    42→ * <UnifiedSpinner source={require('../../../assets/lottie/custom.json')} />
    43→ */
