    57→  const spinnerColor = color || currentTheme.colors.primary;
    58→
    59→  // Get dimensions based on size
    60→  const lottieDimensions = LOTTIE_SIZE_DIMENSIONS[size];
    61→  const nativeDimensions = LOADING_SIZE_DIMENSIONS[size];
    62→  const textFontSize = LOADING_TEXT_SIZES[size];
    63→
    64→  // Android-specific Lottie configuration for merge paths
    65→  useEffect(() => {
    66→    if (Platform.OS === 'android') {
    67→      try {
    68→        const Lottie = require('lottie-react-native');
    69→        if (Lottie.enableMergePathsForKitKatAndAbove) {
    70→          Lottie.enableMergePathsForKitKatAndAbove(true);
    71→        }
    72→      } catch (error) {
    73→        // Silently ignore if merge paths cannot be enabled
    74→      }
    75→    }
    76→  }, []);
    77→
    78→  // Handle Lottie animation failure
    79→  const handleLottieError = (error: any) => {
