    93→          color={spinnerColor}
    94→          testID={testID ? `${testID}-native` : undefined}
    95→        />
    96→      );
    97→    }
    98→
    99→    // Lottie animation with Android-specific optimizations
   100→    return (
   101→      <LottieView
   102→        source={source || require('../../../assets/lottie/loading.json')}
   103→        autoPlay
   104→        loop
   105→        style={{
   106→          width: lottieDimensions,
   107→          height: lottieDimensions,
   108→        }}
   109→        resizeMode="contain"
